{
  "claim": "For non-headline marketplace asking-price series outside the 14-day gate, a median unchanged for 4–21 days is better forecast by Chronos alone than by the current system.",
  "mechanism": "The hypothesis is that marketplace medians move through episodic provider repricing or changes in the offers around the middle, with stable periods between episodes. Chronos's last-value centre and longer context should better represent persistence and the uncertainty of the next episode than the current analog-dominated forecast in this slice.",
  "spec": {
    "when": {
      "all": [
        {"fact": "cls", "op": "==", "value": "marketplace_ask"},
        {"fact": "days_since_change", "op": ">=", "value": 4},
        {"fact": "days_since_change", "op": "<", "value": 22},
        {"fact": "gate14", "op": "==", "value": false},
        {"fact": "in37", "op": "==", "value": false}
      ]
    },
    "do": {
      "action": "members_only",
      "members": ["chronos"]
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least 5 series change, headline skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show improvement.",
  "prior_ids_used": [],
  "expects": "A modest pooled skill increase with headline forecasts unchanged. The supporting marketplace slice has 606 cells across 33 series and Chronos skill +0.215 versus current +0.127; the non-headline restriction, changed-cell count, temporal consistency and bootstrap support remain to be tested."
}
